class ObfuscatedTO(val id: String) {
    private val plain = mutableMapOf<String, String>()
    private val protectedPairs = mutableMapOf<String, String>()
    private var sealedMap: SealedObject? = null                 // JCE

    fun seal(cipher: Cipher) {
        sealedMap = SealedObject(HashMap(protectedPairs), cipher)
        protectedPairs.clear()                                  // drop the plaintext copy
    }
    @Suppress("UNCHECKED_CAST")
    fun unseal(cipher: Cipher) = sealedMap!!.getObject(cipher) as Map<String, String>

    override fun toString() = "ObfuscatedTO(id=$id)"            // never the protected map
}
